using Microsoft.ML.Data;

namespace TicketClassifier.Models;

/// <summary>
/// Raw ticket data loaded from CSV / received from API requests.
/// </summary>
public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

/// <summary>
/// ML.NET prediction output.
/// </summary>
public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public record PredictRequest(string Subject, string Description, int Priority);

public record PredictResponse(
    string PredictedCategory,
    IDictionary<string, float> Confidence);

public record EvaluationMetrics(
    double MicroAccuracy,
    double MacroAccuracy,
    double LogLoss,
    double LogLossReduction);

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

/// <summary>
/// Trains an ML.NET multiclass classifier on startup and exposes
/// prediction + evaluation helpers.
/// </summary>
public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly EvaluationMetrics _metrics;
    private readonly string[] _labelNames;

    public EvaluationMetrics Metrics => _metrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        IDataView data = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        // With a tiny dataset we train on the full set and evaluate on it as well
        // (purely illustrative — a real project would use a train/test split).
        ITransformer model = pipeline.Fit(data);

        // Evaluate
        IDataView predictions = model.Transform(data);
        var eval = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");
        _metrics = new EvaluationMetrics(
            eval.MicroAccuracy,
            eval.MacroAccuracy,
            eval.LogLoss,
            eval.LogLossReduction);

        // Extract ordered label names so we can map Score[] → category
        VBuffer<ReadOnlyMemory<char>> labelBuffer = default;
        predictions.Schema["Score"]
            .GetSlotNames(ref labelBuffer);
        _labelNames = labelBuffer.DenseValues()
            .Select(v => v.ToString())
            .ToArray();

        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(model);
    }

    public PredictResponse Predict(PredictRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        TicketPrediction prediction = _predictionEngine.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _labelNames.Length; i++)
        {
            confidence[_labelNames[i]] = prediction.Score[i];
        }

        return new PredictResponse(prediction.PredictedCategory, confidence);
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketClassifierController : ControllerBase
{
    private readonly TicketClassifierService _service;

    public TicketClassifierController(TicketClassifierService service)
    {
        _service = service;
    }

    /// <summary>
    /// Predict the category for a support ticket.
    /// </summary>
    [HttpPost("predict")]
    public ActionResult<PredictResponse> Predict([FromBody] PredictRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) ||
            string.IsNullOrWhiteSpace(request.Description))
        {
            return BadRequest("Subject and Description are required.");
        }

        if (request.Priority is < 1 or > 3)
        {
            return BadRequest("Priority must be between 1 and 3.");
        }

        return Ok(_service.Predict(request));
    }

    /// <summary>
    /// Return evaluation metrics from the trained model.
    /// </summary>
    [HttpGet("metrics")]
    public ActionResult<EvaluationMetrics> GetMetrics()
    {
        return Ok(_service.Metrics);
    }
}

